    #[test]
    fn incremental_matches_oneshot() {
        let data: Vec<u8> = (0..300_000u32).map(|i| (i % 251) as u8).collect();
        let one = Hasher::new().update(&data).finalize();
        let mut h = Hasher::new();
        for piece in data.chunks(777) {
            h.update(piece);
        }
