//! Greedy word wrapping used for help output, splitting only on ASCII spaces
//! and preserving the indentation of the first word on each paragraph.

/// Display width of a string: every character counts as one column, except
/// characters inside ANSI control sequences (which never occur here anyway).
pub fn display_width(text: &str) -> usize {
    let mut width = 0;
    let mut control_sequence = false;
    for ch in text.chars() {
        if ch.is_ascii_control() {
            control_sequence = true;
        } else if control_sequence && ch == 'm' {
            control_sequence = false;
            continue;
        }
        if !control_sequence {
            width += 1;
        }
    }
    width
}

/// Split a line into words. Each word keeps its trailing spaces attached, and
/// leading whitespace forms a word of its own.
fn find_words(line: &str) -> Vec<&str> {
    let mut words = Vec::new();
    let mut start = 0;
    let mut in_whitespace = false;
    for (idx, ch) in line.char_indices() {
        let next_whitespace = ch == ' ';
        if in_whitespace && !next_whitespace {
            words.push(&line[start..idx]);
            start = idx;
        }
        in_whitespace = next_whitespace;
    }
    if start < line.len() {
        words.push(&line[start..]);
    }
    words
}

struct LineWrapper<'w> {
    hard_width: usize,
    line_width: usize,
    indentation: Option<&'w str>,
}

impl<'w> LineWrapper<'w> {
    fn new(hard_width: usize) -> Self {
        LineWrapper { hard_width, line_width: 0, indentation: None }
    }

    fn reset(&mut self) {
        self.line_width = 0;
        self.indentation = None;
    }

    fn wrap(&mut self, mut words: Vec<&'w str>) -> Vec<&'w str> {
        let mut first_word = false;
        if self.indentation.is_none() {
            first_word = true;
            if let Some(word) = words.first() {
                if word.trim().is_empty() {
                    self.indentation = Some(*word);
                } else {
                    self.indentation = Some("");
                }
            }
        }
        let mut i = 0;
        while i < words.len() {
            let word = words[i];
            let trimmed = word.trim_end();
            let word_width = display_width(trimmed);
            let trimmed_delta = word.len() - trimmed.len();
            if first_word && 0 < word_width {
                first_word = false;
            } else if self.hard_width < self.line_width + word_width {
                if 0 < i {
                    let prev = i - 1;
                    words[prev] = words[prev].trim_end();
                }
                self.line_width = 0;
                words.insert(i, "\n");
                i += 1;
                if let Some(indentation) = self.indentation {
                    words.insert(i, indentation);
                    self.line_width += indentation.len();
                    i += 1;
                }
            }
            self.line_width += word_width + trimmed_delta;
            i += 1;
        }
        words
    }
}

/// Wrap `content` so that no line exceeds `hard_width` columns where possible.
pub fn wrap(content: &str, hard_width: usize) -> String {
    let mut wrapper = LineWrapper::new(hard_width);
    let mut out = String::with_capacity(content.len());
    for (i, line) in content.split_inclusive('\n').enumerate() {
        if 0 < i {
            wrapper.reset();
        }
        let words = find_words(line);
        for piece in wrapper.wrap(words) {
            out.push_str(piece);
        }
    }
    out
}

/// Prefix every line after the first with `trailing`.
pub fn indent(text: &str, trailing: &str) -> String {
    let mut sep = String::from("\n");
    sep.push_str(trailing);
    text.replace('\n', &sep)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn lines(content: &str, width: usize) -> Vec<String> {
        wrap(content, width).trim_end().split('\n').map(|s| s.to_owned()).collect()
    }

    #[test]
    fn basics() {
        assert_eq!(lines("foo", 10), vec!["foo"]);
        assert_eq!(lines("foo bar baz", 5), vec!["foo", "bar", "baz"]);
        assert_eq!(
            lines("To be, or not to be, that is the question.", 10),
            vec!["To be, or", "not to be,", "that is", "the", "question."]
        );
        assert_eq!(lines("foo bar baz", 10), vec!["foo bar", "baz"]);
        assert_eq!(lines("foo", 0), vec!["foo"]);
        assert_eq!(lines("foo bar", 0), vec!["foo", "bar"]);
        assert_eq!(lines("foo bar", usize::MAX), vec!["foo bar"]);
    }
}
EOF
