//! Command line parsing for b3sum, including help output and the diagnostics
//! produced for malformed invocations.

use std::ffi::{OsStr, OsString};
use std::os::unix::ffi::OsStrExt;
use std::path::Path;

use crate::textwrap::{display_width, indent, wrap};

pub const NAME: &str = "b3sum";
pub const VERSION: &str = "1.8.4";

/// Identifier of every argument the program understands, in declaration order.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ArgId {
    Keyed,
    DeriveKey,
    Length,
    Seek,
    NumThreads,
    NoMmap,
    NoNames,
    Raw,
    Tag,
    Check,
    Quiet,
    Help,
    Version,
    File,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Kind {
    Flag,
    Help,
    Version,
    /// An option taking exactly one value of the given type.
    Opt(ValueKind),
    /// The positional argument, which may be given any number of times.
    Positional,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ValueKind {
    U64,
    Usize,
    Str,
    Path,
}

struct Spec {
    id: ArgId,
    long: &'static str,
    short: Option<char>,
    value_name: Option<&'static str>,
    help: &'static str,
    long_help: Option<&'static str>,
    default: Option<&'static str>,
    requires: &'static [ArgId],
    conflicts: &'static [ArgId],
    kind: Kind,
    /// Sort order in the help output.
    display_order: usize,
}

const SPECS: &[Spec] = &[
    Spec {
        id: ArgId::Keyed,
        long: "keyed",
        short: None,
        value_name: None,
        help: "Use the keyed mode, reading the 32-byte key from stdin",
        long_help: None,
        default: None,
        requires: &[ArgId::File],
        conflicts: &[ArgId::DeriveKey],
        kind: Kind::Flag,
        display_order: 0,
    },
    Spec {
        id: ArgId::DeriveKey,
        long: "derive-key",
        short: None,
        value_name: Some("CONTEXT"),
        help: "Use the key derivation mode, with the given context string",
        long_help: Some(
            "Use the key derivation mode, with the given context string\n\nCannot be used with --keyed.",
        ),
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Opt(ValueKind::Str),
        display_order: 1,
    },
    Spec {
        id: ArgId::Length,
        long: "length",
        short: Some('l'),
        value_name: Some("LEN"),
        help: "The number of output bytes, before hex encoding",
        long_help: None,
        default: Some("32"),
        requires: &[],
        conflicts: &[],
        kind: Kind::Opt(ValueKind::U64),
        display_order: 2,
    },
    Spec {
        id: ArgId::Seek,
        long: "seek",
        short: None,
        value_name: Some("SEEK"),
        help: "The starting output byte offset, before hex encoding",
        long_help: None,
        default: Some("0"),
        requires: &[],
        conflicts: &[],
        kind: Kind::Opt(ValueKind::U64),
        display_order: 3,
    },
    Spec {
        id: ArgId::NumThreads,
        long: "num-threads",
        short: None,
        value_name: Some("NUM"),
        help: "The maximum number of threads to use",
        long_help: Some(
            "The maximum number of threads to use\n\nBy default, this is the number of logical cores. If this flag is omitted, or if its value is 0, RAYON_NUM_THREADS is also respected.",
        ),
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Opt(ValueKind::Usize),
        display_order: 4,
    },
    Spec {
        id: ArgId::NoMmap,
        long: "no-mmap",
        short: None,
        value_name: None,
        help: "Disable memory mapping",
        long_help: Some("Disable memory mapping\n\nCurrently this also disables multithreading."),
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Flag,
        display_order: 5,
    },
    Spec {
        id: ArgId::NoNames,
        long: "no-names",
        short: None,
        value_name: None,
        help: "Omit filenames in the output",
        long_help: None,
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Flag,
        display_order: 6,
    },
    Spec {
        id: ArgId::Raw,
        long: "raw",
        short: None,
        value_name: None,
        help: "Write raw output bytes to stdout, rather than hex",
        long_help: Some(
            "Write raw output bytes to stdout, rather than hex\n\n--no-names is implied. In this case, only a single input is allowed.",
        ),
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Flag,
        display_order: 7,
    },
    Spec {
        id: ArgId::Tag,
        long: "tag",
        short: None,
        value_name: None,
        help: "Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]",
        long_help: None,
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Flag,
        display_order: 8,
    },
    Spec {
        id: ArgId::Check,
        long: "check",
        short: Some('c'),
        value_name: None,
        help: "Read BLAKE3 sums from the [FILE]s and check them",
        long_help: None,
        default: None,
        requires: &[],
        conflicts: &[ArgId::DeriveKey, ArgId::Keyed, ArgId::Length, ArgId::Raw, ArgId::Tag, ArgId::NoNames],
        kind: Kind::Flag,
        display_order: 9,
    },
    Spec {
        id: ArgId::Quiet,
        long: "quiet",
        short: None,
        value_name: None,
        help: "Skip printing OK for each checked file",
        long_help: Some("Skip printing OK for each checked file\n\nMust be used with --check."),
        default: None,
        requires: &[ArgId::Check],
        conflicts: &[],
        kind: Kind::Flag,
        display_order: 10,
    },
    Spec {
        id: ArgId::Help,
        long: "help",
        short: Some('h'),
        value_name: None,
        help: "Print help (see more with '--help')",
        long_help: Some("Print help (see a summary with '-h')"),
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Help,
        display_order: 999,
    },
    Spec {
        id: ArgId::Version,
        long: "version",
        short: Some('V'),
        value_name: None,
        help: "Print version",
        long_help: None,
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Version,
        display_order: 999,
    },
    Spec {
        id: ArgId::File,
        long: "",
        short: None,
        value_name: Some("FILE"),
        help: "Files to hash, or checkfiles to check",
        long_help: Some(
            "Files to hash, or checkfiles to check\n\nWhen no file is given, or when - is given, read standard input.",
        ),
        default: None,
        requires: &[],
        conflicts: &[],
        kind: Kind::Positional,
        display_order: 0,
    },
];

fn spec(id: ArgId) -> &'static Spec {
    SPECS.iter().find(|s| s.id == id).expect("every argument has a spec")
}

fn find_long(long: &str) -> Option<&'static Spec> {
    SPECS.iter().find(|s| s.kind != Kind::Positional && s.long == long)
}

fn find_short(short: char) -> Option<&'static Spec> {
    SPECS.iter().find(|s| s.short == Some(short))
}

impl Spec {
    fn is_positional(&self) -> bool {
        self.kind == Kind::Positional
    }

    fn takes_value(&self) -> bool {
        matches!(self.kind, Kind::Opt(_) | Kind::Positional)
    }

    /// The textual form used in usage strings and diagnostics, e.g.
    /// `--length <LEN>` or `[FILE]...`. For the positional, `required`
    /// chooses between `<FILE>...` and `[FILE]...`.
    fn render(&self, required: Option<bool>) -> String {
        let mut s = String::new();
        if !self.is_positional() {
            s.push_str("--");
            s.push_str(self.long);
        }
        s.push_str(&self.render_suffix(required));
        s
    }

    fn render_suffix(&self, required: Option<bool>) -> String {
        let mut s = String::new();
        match self.kind {
            Kind::Opt(_) => {
                s.push(' ');
                s.push('<');
                s.push_str(self.value_name.unwrap_or(""));
                s.push('>');
            }
            Kind::Positional => {
                let required = required.unwrap_or(false);
                let name = self.value_name.unwrap_or("");
                if required {
                    s.push_str(&format!("<{}>", name));
                } else {
                    s.push_str(&format!("[{}]", name));
                }
                s.push_str("...");
            }
            _ => {}
        }
        s
    }
}

/// The result of successfully parsing the command line.
#[derive(Debug, Clone)]
pub struct Args {
    pub keyed: bool,
    pub derive_key: Option<String>,
    pub length: u64,
    pub seek: u64,
    pub num_threads: Option<usize>,
    pub no_mmap: bool,
    pub no_names: bool,
    pub raw: bool,
    pub tag: bool,
    pub check: bool,
    pub quiet: bool,
    pub files: Vec<OsString>,
}

/// A request to print something and exit, produced instead of running.
#[derive(Debug, Clone)]
pub struct Exit {
    pub message: String,
    pub to_stderr: bool,
    pub code: i32,
}

impl Exit {
    fn error(message: String) -> Self {
        Exit { message, to_stderr: true, code: 2 }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Ident {
    Short,
    Long,
    Index,
}

/// A value for an argument that has been seen but not yet committed.
struct Pending {
    id: ArgId,
    ident: Option<Ident>,
    raw_vals: Vec<OsString>,
}

#[derive(Default)]
struct Matched {
    explicit: bool,
    raw_vals: Vec<OsString>,
}

/// Which arguments have been matched, in the order they were first seen.
#[derive(Default)]
struct Matcher {
    args: Vec<(ArgId, Matched)>,
    pending: Option<Pending>,
}

impl Matcher {
    fn get(&self, id: ArgId) -> Option<&Matched> {
        self.args.iter().find(|(i, _)| *i == id).map(|(_, m)| m)
    }

    fn is_present(&self, id: ArgId) -> bool {
        self.get(id).map(|m| m.explicit).unwrap_or(false)
    }

    fn present_ids(&self) -> Vec<ArgId> {
        self.args.iter().filter(|(_, m)| m.explicit).map(|(id, _)| *id).collect()
    }

    fn remove(&mut self, id: ArgId) -> bool {
        let before = self.args.len();
        self.args.retain(|(i, _)| *i != id);
        before != self.args.len()
    }

    fn start(&mut self, id: ArgId, explicit: bool) {
        if let Some(pos) = self.args.iter().position(|(i, _)| *i == id) {
            self.args[pos].1.explicit = explicit;
        } else {
            self.args.push((id, Matched { explicit, raw_vals: Vec::new() }));
        }
    }

    fn push_val(&mut self, id: ArgId, val: OsString) {
        if let Some(pos) = self.args.iter().position(|(i, _)| *i == id) {
            self.args[pos].1.raw_vals.push(val);
        }
    }

    fn pending_values_mut(&mut self, id: ArgId, ident: Option<Ident>) -> &mut Vec<OsString> {
        let pending = self.pending.get_or_insert_with(|| Pending { id, ident, raw_vals: Vec::new() });
        &mut pending.raw_vals
    }
}

enum ParseState {
    ValuesDone,
    Opt(ArgId),
    Pos(ArgId),
}

enum ParseResult {
    NoArg,
    ValuesDone,
    Opt(ArgId),
    NoMatchingArg(String),
    UnneededAttachedValue { rest: String, used: Vec<ArgId>, arg: String },
}

pub struct Parser {
    bin_name: String,
    matcher: Matcher,
}

/// Parse the full argument vector (including the program name).
pub fn parse(argv: &[OsString]) -> Result<Args, Exit> {
    let bin_name = argv
        .first()
        .and_then(|a| Path::new(a).file_name())
        .and_then(|f| f.to_str())
        .map(|s| s.to_owned())
        .unwrap_or_else(|| NAME.to_owned());
    let mut parser = Parser { bin_name, matcher: Matcher::default() };
    let rest = if argv.is_empty() { &argv[..] } else { &argv[1..] };
    parser.parse(rest)?;
    parser.validate()?;
    Ok(parser.into_args())
}

impl Parser {
    fn parse(&mut self, args: &[OsString]) -> Result<(), Exit> {
        let mut parse_state = ParseState::ValuesDone;
        let mut trailing_values = false;

        for arg_os in args {
            let arg_os = arg_os.as_os_str();
            if !trailing_values {
                if arg_os == "--" {
                    trailing_values = true;
                    continue;
                } else if let Some((long_arg, long_value)) = to_long(arg_os) {
                    let result = self.parse_long_arg(long_arg, long_value)?;
                    match result {
                        ParseResult::ValuesDone => {
                            parse_state = ParseState::ValuesDone;
                            continue;
                        }
                        ParseResult::Opt(id) => {
                            parse_state = ParseState::Opt(id);
                            continue;
                        }
                        ParseResult::NoMatchingArg(arg) => {
                            let _ = self.resolve_pending();
                            return Err(self.did_you_mean_error(&arg, trailing_values));
                        }
                        ParseResult::UnneededAttachedValue { rest, used, arg } => {
                            let _ = self.resolve_pending();
                            let usage = self.usage(&used, &[]);
                            return Err(too_many_values(&rest, &arg, &usage));
                        }
                        ParseResult::NoArg => unreachable!(),
                    }
                } else if let Some(short) = to_short(arg_os) {
                    let result = self.parse_short_arg(short)?;
                    match result {
                        ParseResult::NoArg => {}
                        ParseResult::ValuesDone => {
                            parse_state = ParseState::ValuesDone;
                            continue;
                        }
                        ParseResult::Opt(id) => {
                            parse_state = ParseState::Opt(id);
                            continue;
                        }
                        ParseResult::NoMatchingArg(arg) => {
                            let _ = self.resolve_pending();
                            let suggested_trailing_arg = !trailing_values;
                            let usage = self.usage(&[], &[]);
                            return Err(unknown_argument(&arg, None, suggested_trailing_arg, &usage));
                        }
                        ParseResult::UnneededAttachedValue { .. } => unreachable!(),
                    }
                }

                if let ParseState::Opt(id) = parse_state {
                    // A value for the option that is waiting for one.
                    let vals = self.matcher.pending_values_mut(id, None);
                    vals.push(arg_os.to_owned());
                    // Every option here takes exactly one value.
                    parse_state = ParseState::ValuesDone;
                    continue;
                }
            }

            // Positional argument.
            let pending_is_file = self.matcher.pending.as_ref().map(|p| p.id == ArgId::File).unwrap_or(false);
            if !pending_is_file {
                self.resolve_pending()?;
            }
            let vals = self.matcher.pending_values_mut(ArgId::File, Some(Ident::Index));
            vals.push(arg_os.to_owned());
            parse_state = ParseState::Pos(ArgId::File);
        }
        let _ = parse_state;

        self.resolve_pending()?;
        // Defaults for options that were not given.
        for s in SPECS {
            if let Some(default) = s.default {
                if self.matcher.get(s.id).is_none() {
                    self.matcher.start(s.id, false);
                    self.matcher.push_val(s.id, OsString::from(default));
                }
            }
        }
        Ok(())
    }

    fn parse_long_arg(
        &mut self,
        long_arg: Result<&str, &OsStr>,
        long_value: Option<&OsStr>,
    ) -> Result<ParseResult, Exit> {
        let long_arg = match long_arg {
            Ok(l) => l,
            Err(os) => return Ok(ParseResult::NoMatchingArg(os.to_string_lossy().into_owned())),
        };
        if let Some(s) = find_long(long_arg) {
            if s.takes_value() {
                let has_eq = long_value.is_some();
                self.parse_opt_value(Ident::Long, long_value, s, has_eq)
            } else if let Some(rest) = long_value {
                let mut used: Vec<ArgId> = self.matcher.present_ids();
                used.push(s.id);
                Ok(ParseResult::UnneededAttachedValue {
                    rest: rest.to_string_lossy().into_owned(),
                    used,
                    arg: s.render(None),
                })
            } else {
                self.react(Some(Ident::Long), s, Vec::new())
            }
        } else {
            Ok(ParseResult::NoMatchingArg(long_arg.to_owned()))
        }
    }

    fn parse_short_arg(&mut self, short: &OsStr) -> Result<ParseResult, Exit> {
        let bytes = short.as_bytes();
        // Split into the valid UTF-8 prefix and any invalid suffix.
        let (prefix, suffix) = match std::str::from_utf8(bytes) {
            Ok(s) => (s, None),
            Err(e) => {
                let valid = e.valid_up_to();
                (std::str::from_utf8(&bytes[..valid]).unwrap(), Some(&bytes[valid..]))
            }
        };
        let mut ret = ParseResult::NoArg;
        let mut chars = prefix.char_indices();
        loop {
            let (idx, c) = match chars.next() {
                Some(x) => x,
                None => {
                    if let Some(suffix) = suffix {
                        let rest = OsStr::from_bytes(suffix);
                        return Ok(ParseResult::NoMatchingArg(format!("-{}", rest.to_string_lossy())));
                    }
                    break;
                }
            };
            if let Some(s) = find_short(c) {
                if !s.takes_value() {
                    ret = self.react(Some(Ident::Short), s, Vec::new())?;
                    continue;
                }
                // Anything after the flag is an attached value.
                let after = &bytes[idx + c.len_utf8()..];
                let val = if after.is_empty() { None } else { Some(OsStr::from_bytes(after)) };
                let (val, has_eq) = match val.and_then(|v| v.as_bytes().strip_prefix(b"=")) {
                    Some(v) => (Some(OsStr::from_bytes(v)), true),
                    None => (val, false),
                };
                return self.parse_opt_value(Ident::Short, val, s, has_eq);
            }
            return Ok(ParseResult::NoMatchingArg(format!("-{}", c)));
        }
        Ok(ret)
    }

    fn parse_opt_value(
        &mut self,
        ident: Ident,
        attached_value: Option<&OsStr>,
        s: &'static Spec,
        _has_eq: bool,
    ) -> Result<ParseResult, Exit> {
        if let Some(v) = attached_value {
            self.react(Some(ident), s, vec![v.to_owned()])?;
            Ok(ParseResult::ValuesDone)
        } else {
            self.resolve_pending()?;
            self.matcher.pending_values_mut(s.id, Some(ident));
            Ok(ParseResult::Opt(s.id))
        }
    }

    fn resolve_pending(&mut self) -> Result<(), Exit> {
        let pending = match self.matcher.pending.take() {
            Some(p) => p,
            None => return Ok(()),
        };
        let s = spec(pending.id);
        self.react(pending.ident, s, pending.raw_vals)?;
        Ok(())
    }

    fn react(&mut self, ident: Option<Ident>, s: &'static Spec, raw_vals: Vec<OsString>) -> Result<ParseResult, Exit> {
        self.resolve_pending()?;
        // Check the number of values.
        match s.kind {
            Kind::Opt(_) | Kind::Positional => {
                if raw_vals.is_empty() {
                    return Err(empty_value(&s.render(None)));
                }
            }
            _ => {}
        }
        match s.kind {
            Kind::Opt(_) | Kind::Flag => {
                if self.matcher.remove(s.id) {
                    let usage = self.usage(&[], &[]);
                    let name = s.render(None);
                    return Err(argument_conflict(&name, &[name.clone()], &usage));
                }
                self.matcher.start(s.id, true);
                let vals = if s.kind == Kind::Flag { vec![OsString::from("true")] } else { raw_vals };
                self.push_arg_values(s, vals)?;
                Ok(ParseResult::ValuesDone)
            }
            Kind::Positional => {
                self.matcher.start(s.id, true);
                self.push_arg_values(s, raw_vals)?;
                Ok(ParseResult::ValuesDone)
            }
            Kind::Help => {
                let use_long = !matches!(ident, Some(Ident::Short));
                Err(Exit { message: self.render_help(use_long), to_stderr: false, code: 0 })
            }
            Kind::Version => Err(Exit { message: format!("{} {}\n", NAME, VERSION), to_stderr: false, code: 0 }),
        }
    }

    fn push_arg_values(&mut self, s: &'static Spec, raw_vals: Vec<OsString>) -> Result<(), Exit> {
        for raw in raw_vals {
            self.validate_value(s, &raw)?;
            self.matcher.push_val(s.id, raw);
        }
        Ok(())
    }

    fn validate_value(&self, s: &'static Spec, raw: &OsStr) -> Result<(), Exit> {
        match s.kind {
            Kind::Opt(ValueKind::U64) | Kind::Opt(ValueKind::Usize) => {
                let text = match raw.to_str() {
                    Some(t) => t,
                    None => return Err(invalid_utf8(&self.usage(&[], &[]))),
                };
                let parsed: Result<u64, std::num::ParseIntError> = text.parse::<u64>();
                if let Err(e) = parsed {
                    return Err(value_validation(&s.render(None), text, &e.to_string()));
                }
            }
            Kind::Opt(ValueKind::Str) => {
                if raw.to_str().is_none() {
                    return Err(invalid_utf8(&self.usage(&[], &[])));
                }
            }
            Kind::Opt(ValueKind::Path) | Kind::Positional => {
                if raw.is_empty() {
                    return Err(empty_value(&s.render(None)));
                }
            }
            _ => {}
        }
        Ok(())
    }

    fn did_you_mean_error(&mut self, arg: &str, trailing_values: bool) -> Exit {
        let longs: Vec<&str> = SPECS.iter().filter(|s| !s.is_positional()).map(|s| s.long).collect();
        let suggestion = did_you_mean(arg, &longs).pop();
        if let Some(name) = suggestion.as_ref() {
            if let Some(s) = find_long(name) {
                self.matcher.start(s.id, true);
            }
        }
        let suggestion = suggestion.map(|s| format!("--{}", s));
        let used = self.matcher.present_ids();
        let suggested_trailing_arg = suggestion.is_none() && !trailing_values;
        let usage = self.usage(&used, &[]);
        unknown_argument(&format!("--{}", arg), suggestion, suggested_trailing_arg, &usage)
    }

    /// Checks run after parsing: conflicts, then requirements.
    fn validate(&mut self) -> Result<(), Exit> {
        let present = self.matcher.present_ids();

        // Conflicts.
        for &id in &present {
            let conflicts = gather_conflicts(&present, id);
            if conflicts.is_empty() {
                continue;
            }
            let mut dedup: Vec<ArgId> = Vec::new();
            for c in conflicts {
                if !dedup.contains(&c) {
                    dedup.push(c);
                }
            }
            let names: Vec<String> = dedup.iter().map(|c| spec(*c).render(None)).collect();
            let used_filtered: Vec<ArgId> = present.iter().copied().filter(|k| !dedup.contains(k)).collect();
            let mut required: Vec<ArgId> = Vec::new();
            for &k in &used_filtered {
                for &r in spec(k).requires {
                    if !used_filtered.contains(&r) && !dedup.contains(&r) {
                        required.push(r);
                    }
                }
            }
            required.extend(used_filtered.iter().copied());
            let usage = self.usage(&required, &[]);
            return Err(argument_conflict(&spec(id).render(None), &names, &usage));
        }

        // Requirements.
        let mut required_graph: Vec<ArgId> = Vec::new();
        for &id in &present {
            for &r in spec(id).requires {
                if !required_graph.contains(&r) {
                    required_graph.push(r);
                }
            }
        }
        let mut missing: Vec<ArgId> = Vec::new();
        for &r in &required_graph {
            if self.matcher.is_present(r) {
                continue;
            }
            // A missing requirement is acceptable if it conflicts with something present.
            if !gather_conflicts(&present, r).is_empty() {
                continue;
            }
            missing.push(r);
        }
        if !missing.is_empty() {
            let req_args = self.required_usage_from(&missing, &required_graph);
            let mut used = present.clone();
            used.extend(missing.iter().copied());
            let usage = self.usage(&used, &required_graph);
            return Err(missing_required_argument(&req_args, &usage));
        }
        Ok(())
    }

    /// The list of required arguments (for the "not provided" error).
    fn required_usage_from(&self, incls: &[ArgId], required_graph: &[ArgId]) -> Vec<String> {
        let mut opts: Vec<String> = Vec::new();
        let mut positional: Option<String> = None;
        for &req in required_graph.iter().chain(incls.iter()) {
            if self.matcher.is_present(req) {
                continue;
            }
            let s = spec(req);
            let rendered = s.render(Some(true));
            if s.is_positional() {
                positional = Some(rendered);
            } else if !opts.contains(&rendered) {
                opts.push(rendered);
            }
        }
        if let Some(p) = positional {
            opts.push(p);
        }
        opts
    }

    /// Build the usage line. With no `used` arguments this is the generic
    /// `[OPTIONS] [FILE]...` form; otherwise it lists the given arguments.
    fn usage(&self, used: &[ArgId], required_graph: &[ArgId]) -> String {
        let mut out = String::from("Usage: ");
        out.push_str(&self.bin_name);
        out.push(' ');
        if used.is_empty() {
            out.push_str("[OPTIONS] ");
        }
        let mut required_opts: Vec<String> = Vec::new();
        let mut positional: Option<String> = None;
        for &req in required_graph.iter().chain(used.iter()) {
            let s = spec(req);
            let rendered = s.render(Some(true));
            if s.is_positional() {
                positional = Some(rendered);
            } else if !required_opts.contains(&rendered) {
                required_opts.push(rendered);
            }
        }
        if positional.is_none() {
            positional = Some(spec(ArgId::File).render(Some(false)));
        }
        for opt in required_opts {
            out.push_str(&opt);
            out.push(' ');
        }
        if let Some(p) = positional {
            out.push_str(&p);
            out.push(' ');
        }
        out.trim_end().to_owned()
    }

    fn into_args(self) -> Args {
        let m = &self.matcher;
        let flag = |id: ArgId| m.is_present(id);
        let value = |id: ArgId| m.get(id).and_then(|x| x.raw_vals.last().cloned());
        let number = |id: ArgId| value(id).and_then(|v| v.to_str().and_then(|t| t.parse::<u64>().ok()));
        Args {
            keyed: flag(ArgId::Keyed),
            derive_key: if m.is_present(ArgId::DeriveKey) {
                value(ArgId::DeriveKey).map(|v| v.to_string_lossy().into_owned())
            } else {
                None
            },
            length: number(ArgId::Length).unwrap_or(32),
            seek: number(ArgId::Seek).unwrap_or(0),
            num_threads: if m.is_present(ArgId::NumThreads) {
                number(ArgId::NumThreads).map(|n| n as usize)
            } else {
                None
            },
            no_mmap: flag(ArgId::NoMmap),
            no_names: flag(ArgId::NoNames),
            raw: flag(ArgId::Raw),
            tag: flag(ArgId::Tag),
            check: flag(ArgId::Check),
            quiet: flag(ArgId::Quiet),
            files: m.get(ArgId::File).map(|x| x.raw_vals.clone()).unwrap_or_default(),
        }
    }

    // ----- help output -----

    fn render_help(&self, use_long: bool) -> String {
        let term_w = term_width();
        let mut out = String::new();
        out.push_str("Usage: ");
        out.push_str(&self.usage(&[], &[])["Usage: ".len()..]);
        out.push_str("\n\n");

        let positionals: Vec<&Spec> = SPECS.iter().filter(|s| s.is_positional()).collect();
        let options: Vec<&Spec> = SPECS.iter().filter(|s| !s.is_positional()).collect();

        out.push_str("Arguments:\n");
        write_args(&mut out, &positionals, use_long, term_w);
        out.push_str("\n\n");
        out.push_str("Options:\n");
        write_args(&mut out, &options, use_long, term_w);

        let trimmed = out.trim_end();
        let mut result = trimmed.trim_start_matches('\n').to_owned();
        result.push('\n');
        result
    }
}

const TAB: &str = "  ";
const TAB_WIDTH: usize = 2;
const NEXT_LINE_INDENT: &str = "        ";
const SHORT_SIZE: usize = 4;

fn sort_key(s: &Spec) -> (usize, String) {
    if s.is_positional() {
        return (1, String::new());
    }
    let key = if let Some(x) = s.short {
        let mut k = x.to_ascii_lowercase().to_string();
        k.push(if x.is_ascii_lowercase() { '0' } else { '1' });
        k
    } else {
        s.long.to_string()
    };
    (s.display_order, key)
}

fn spec_vals(s: &Spec, use_long: bool) -> String {
    let mut vals = Vec::new();
    if s.takes_value() {
        if let Some(d) = s.default {
            vals.push(format!("[default: {}]", d));
        }
    }
    let connector = if use_long { "\n" } else { " " };
    vals.join(connector)
}

fn arg_next_line_help(s: &Spec, spec_vals: &str, longest: usize, use_long: bool, term_w: usize) -> bool {
    if use_long {
        return true;
    }
    let h_w = display_width(s.help) + display_width(spec_vals);
    let taken = longest + TAB_WIDTH * 2;
    term_w >= taken && (taken as f32 / term_w as f32) > 0.40 && h_w > (term_w - taken)
}

fn write_args(out: &mut String, args: &[&Spec], use_long: bool, term_w: usize) {
    let mut longest = 2;
    let mut ordered: Vec<((usize, String), &Spec)> = Vec::new();
    for &s in args {
        let width = display_width(&s.render(None));
        let actual = if !s.is_positional() { width + SHORT_SIZE } else { width };
        longest = longest.max(actual);
        ordered.push((sort_key(s), s));
    }
    ordered.sort_by(|a, b| a.0.cmp(&b.0));
    let next_line_help = args.iter().any(|s| arg_next_line_help(s, &spec_vals(s, use_long), longest, use_long, term_w));
    for (i, (_, s)) in ordered.iter().enumerate() {
        if i != 0 {
            out.push('\n');
            if next_line_help && use_long {
                out.push('\n');
            }
        }
        write_arg(out, s, next_line_help, longest, use_long, term_w);
    }
}

fn write_arg(out: &mut String, s: &Spec, next_line_help: bool, longest: usize, use_long: bool, term_w: usize) {
    let specs = spec_vals(s, use_long);
    out.push_str(TAB);
    // Short and long switches.
    if let Some(c) = s.short {
        out.push('-');
        out.push(c);
    } else if !s.is_positional() {
        out.push_str("    ");
    }
    if !s.is_positional() {
        if s.short.is_some() {
            out.push_str(", ");
        }
        out.push_str("--");
        out.push_str(s.long);
    }
    out.push_str(&s.render_suffix(None));
    // Alignment padding.
    let padding = if use_long || next_line_help {
        0
    } else if !s.is_positional() {
        let self_len = display_width(&s.render(None)) + SHORT_SIZE;
        longest + TAB_WIDTH - self_len
    } else {
        let self_len = display_width(&s.render(None));
        longest + TAB_WIDTH - self_len
    };
    for _ in 0..padding {
        out.push(' ');
    }
    let about = if use_long { s.long_help.unwrap_or(s.help) } else { s.help };
    write_help_text(out, about, &specs, next_line_help, longest, use_long, term_w);
}

fn write_help_text(
    out: &mut String,
    about: &str,
    spec_vals: &str,
    next_line_help: bool,
    longest: usize,
    use_long: bool,
    term_w: usize,
) {
    if next_line_help {
        out.push('\n');
        out.push_str(TAB);
        out.push_str(NEXT_LINE_INDENT);
    }
    let spaces = if next_line_help { TAB.len() + NEXT_LINE_INDENT.len() } else { longest + TAB_WIDTH * 2 };
    let trailing_indent = " ".repeat(spaces);
    let mut help = about.to_owned();
    let mut help_is_empty = help.is_empty();
    help = help.replace("{n}", "\n");
    let next_line_specs = use_long;
    if !spec_vals.is_empty() && !next_line_specs {
        if !help_is_empty {
            help.push(' ');
        }
        help.push_str(spec_vals);
        help_is_empty = help.is_empty();
    }
    let avail_chars = term_w.saturating_sub(spaces);
    let wrapped = wrap(&help, avail_chars);
    out.push_str(&indent(&wrapped, &trailing_indent));
    if !spec_vals.is_empty() && next_line_specs {
        let mut extra = String::new();
        if !help_is_empty {
            extra.push_str("\n\n");
        }
        extra.push_str(spec_vals);
        let wrapped = wrap(&extra, avail_chars);
        out.push_str(&indent(&wrapped, &trailing_indent));
    }
}

// ----- terminal size -----

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

fn terminal_size_of(fd: i32) -> Option<usize> {
    unsafe {
        if isatty(fd) == 0 {
            return None;
        }
        let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) != 0 {
            return None;
        }
        if ws.ws_row > 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else {
            None
        }
    }
}

fn term_width() -> usize {
    for fd in [1, 2, 0] {
        if let Some(w) = terminal_size_of(fd) {
            return w;
        }
    }
    std::env::var_os("COLUMNS")
        .and_then(|v| v.to_str().map(|s| s.to_owned()))
        .and_then(|s| s.parse::<usize>().ok())
        .unwrap_or(100)
}

// ----- lexing helpers -----

/// Split `--flag=value` style arguments. Returns None unless the argument
/// starts with `--` and is not exactly `--`.
fn to_long(arg: &OsStr) -> Option<(Result<&str, &OsStr>, Option<&OsStr>)> {
    let bytes = arg.as_bytes();
    let remainder = bytes.strip_prefix(b"--")?;
    if remainder.is_empty() {
        return None;
    }
    let (flag, value) = match remainder.iter().position(|&b| b == b'=') {
        Some(p) => (&remainder[..p], Some(OsStr::from_bytes(&remainder[p + 1..]))),
        None => (remainder, None),
    };
    let flag = match std::str::from_utf8(flag) {
        Ok(f) => Ok(f),
        Err(_) => Err(OsStr::from_bytes(flag)),
    };
    Some((flag, value))
}

/// The cluster of short flags in `-abc`, if the argument looks like one.
fn to_short(arg: &OsStr) -> Option<&OsStr> {
    let bytes = arg.as_bytes();
    let remainder = bytes.strip_prefix(b"-")?;
    if remainder.starts_with(b"-") || remainder.is_empty() {
        None
    } else {
        Some(OsStr::from_bytes(remainder))
    }
}

// ----- conflicts -----

fn direct_conflicts(id: ArgId) -> &'static [ArgId] {
    spec(id).conflicts
}

/// All present arguments that conflict with `id`, in either direction.
fn gather_conflicts(present: &[ArgId], id: ArgId) -> Vec<ArgId> {
    let mut conflicts = Vec::new();
    let own = direct_conflicts(id);
    for &other in present {
        if other == id {
            continue;
        }
        if own.contains(&other) {
            conflicts.push(other);
        }
        if direct_conflicts(other).contains(&id) {
            conflicts.push(other);
        }
    }
    conflicts
}

// ----- suggestions -----

/// Jaro similarity between two strings, by characters.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for (i, &a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = b_len.min(i + search_range + 1);
        for j in 0..max_bound {
            if min_bound <= j && a_elem == b[j] && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    let mut transpositions = 0usize;
    if matches != 0 {
        let mut j = 0;
        for (i, &flag) in a_flags.iter().enumerate() {
            if flag {
                while j < b_len && !b_flags[j] {
                    j += 1;
                }
                if j < b_len {
                    if a[i] != b[j] {
                        transpositions += 1;
                    }
                    j += 1;
                }
            }
        }
    }
    transpositions /= 2;
    if matches == 0 {
        0.0
    } else {
        ((matches as f64 / a_len as f64)
            + (matches as f64 / b_len as f64)
            + ((matches - transpositions) as f64 / matches as f64))
            / 3.0
    }
}

/// Candidates similar to `v`, in ascending order of similarity.
fn did_you_mean(v: &str, possible: &[&str]) -> Vec<String> {
    let mut candidates: Vec<(f64, String)> = Vec::new();
    for pv in possible {
        let confidence = jaro(v, pv);
        if confidence > 0.7 {
            // Insert after any existing candidate with equal or lower confidence.
            let pos = candidates.iter().position(|c| c.0 > confidence).unwrap_or(candidates.len());
            candidates.insert(pos, (confidence, pv.to_string()));
        }
    }
    candidates.into_iter().map(|(_, s)| s).collect()
}

// ----- error formatting -----

fn try_help(out: &mut String) {
    out.push_str("\n\nFor more information, try '--help'.\n");
}

fn put_usage(out: &mut String, usage: &str) {
    out.push_str("\n\n");
    out.push_str(usage);
}

fn unknown_argument(arg: &str, did_you_mean: Option<String>, suggested_trailing_arg: bool, usage: &str) -> Exit {
    let mut out = String::from("error: ");
    out.push_str(&format!("unexpected argument '{}' found", arg));
    let mut suggested = false;
    if let Some(flag) = did_you_mean {
        out.push('\n');
        out.push('\n');
        suggested = true;
        out.push_str(&format!("{}tip: a similar argument exists: '{}'", TAB, flag));
    }
    if suggested_trailing_arg {
        if !suggested {
            out.push('\n');
        }
        out.push_str(&format!("\n{}tip: to pass '{}' as a value, use '-- {}'", TAB, arg, arg));
    }
    put_usage(&mut out, usage);
    try_help(&mut out);
    Exit::error(out)
}

fn too_many_values(val: &str, arg: &str, usage: &str) -> Exit {
    let mut out = String::from("error: ");
    out.push_str(&format!("unexpected value '{}' for '{}' found; no more were expected", val, arg));
    put_usage(&mut out, usage);
    try_help(&mut out);
    Exit::error(out)
}

fn empty_value(arg: &str) -> Exit {
    let mut out = String::from("error: ");
    out.push_str(&format!("a value is required for '{}' but none was supplied", arg));
    try_help(&mut out);
    Exit::error(out)
}

fn value_validation(arg: &str, val: &str, source: &str) -> Exit {
    let mut out = String::from("error: ");
    out.push_str(&format!("invalid value '{}' for '{}': {}", val, arg, source));
    try_help(&mut out);
    Exit::error(out)
}

fn invalid_utf8(usage: &str) -> Exit {
    let mut out = String::from("error: ");
    out.push_str("invalid UTF-8 was detected in one or more arguments");
    put_usage(&mut out, usage);
    try_help(&mut out);
    Exit::error(out)
}

fn argument_conflict(arg: &str, others: &[String], usage: &str) -> Exit {
    let mut out = String::from("error: ");
    if others.len() == 1 && others[0] == arg {
        out.push_str(&format!("the argument '{}' cannot be used multiple times", arg));
    } else {
        out.push_str(&format!("the argument '{}' cannot be used with", arg));
        if others.len() == 1 {
            out.push_str(&format!(" '{}'", others[0]));
        } else if others.is_empty() {
            out.push_str(" one or more of the other specified arguments");
        } else {
            out.push(':');
            for v in others {
                out.push_str(&format!("\n{}{}", TAB, v));
            }
        }
    }
    put_usage(&mut out, usage);
    try_help(&mut out);
    Exit::error(out)
}

fn missing_required_argument(req_args: &[String], usage: &str) -> Exit {
    let mut out = String::from("error: ");
    out.push_str("the following required arguments were not provided:");
    for v in req_args {
        out.push_str(&format!("\n{}{}", TAB, v));
    }
    put_usage(&mut out, usage);
    try_help(&mut out);
    Exit::error(out)
}

