//! b3sum: compute and check BLAKE3 checksums.

mod blake3;
mod cli;
mod textwrap;

use std::ffi::OsString;
use std::fs::File;
use std::io::{self, Read, Write};

use blake3::Hasher;
use cli::Args;

/// A failure that aborts the whole run; printed as `Error: ...` with exit code 1.
struct Fatal(String);

impl From<io::Error> for Fatal {
    fn from(e: io::Error) -> Self {
        Fatal(e.to_string())
    }
}

type Result<T> = std::result::Result<T, Fatal>;

fn main() {
    let argv: Vec<OsString> = std::env::args_os().collect();
    let args = match cli::parse(&argv) {
        Ok(args) => args,
        Err(exit) => {
            // Output problems while reporting usage errors are deliberately ignored.
            if exit.to_stderr {
                let stderr = io::stderr();
                let mut lock = stderr.lock();
                let _ = lock.write_all(exit.message.as_bytes());
                let _ = lock.flush();
            } else {
                let stdout = io::stdout();
                let mut lock = stdout.lock();
                let _ = lock.write_all(exit.message.as_bytes());
                let _ = lock.flush();
            }
            std::process::exit(exit.code);
        }
    };

    // All the work happens on a worker thread (the hashing is parallel, and the
    // main thread merely waits for the result).
    let worker = std::thread::Builder::new().spawn(move || run(args)).expect("failed to spawn worker thread");
    match worker.join() {
        Ok(Ok(code)) => std::process::exit(code),
        Ok(Err(Fatal(msg))) => {
            eprintln!("Error: {}", msg);
            std::process::exit(1);
        }
        Err(panic) => std::panic::resume_unwind(panic),
    }
}

fn thread_count(args: &Args) -> usize {
    match args.num_threads {
        Some(n) if n > 0 => n,
        _ => {
            let from_env = std::env::var("RAYON_NUM_THREADS").ok().and_then(|s| s.parse::<usize>().ok());
            match from_env {
                Some(n) if n > 0 => n,
                _ => std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1),
            }
        }
    }
}

fn read_key_from_stdin() -> Result<[u8; blake3::KEY_LEN]> {
    let mut buf = [0u8; blake3::KEY_LEN + 1];
    let mut filled = 0;
    let stdin = io::stdin();
    let mut lock = stdin.lock();
    while filled < buf.len() {
        let n = lock.read(&mut buf[filled..])?;
        if n == 0 {
            break;
        }
        filled += n;
    }
    if filled > blake3::KEY_LEN {
        return Err(Fatal(format!("read more than {} key bytes from stdin", blake3::KEY_LEN)));
    }
    if filled < blake3::KEY_LEN {
        return Err(Fatal(format!("expected {} key bytes from stdin, found {}", blake3::KEY_LEN, filled)));
    }
    let mut key = [0u8; blake3::KEY_LEN];
    key.copy_from_slice(&buf[..blake3::KEY_LEN]);
    Ok(key)
}

fn run(args: Args) -> Result<i32> {
    let threads = thread_count(&args);

    let mut base_hasher = if args.keyed {
        let key = read_key_from_stdin()?;
        Hasher::new_keyed(&key)
    } else if let Some(context) = args.derive_key.as_deref() {
        Hasher::new_derive_key(context)
    } else {
        Hasher::new()
    };
    base_hasher.set_threads(threads);

    let mut files = args.files.clone();
    if files.is_empty() {
        files.push(OsString::from("-"));
    }
    if args.raw && files.len() > 1 {
        return Err(Fatal("Only one filename can be provided when using --raw".to_owned()));
    }

    let mut some_file_failed = false;
    let mut files_failed: u64 = 0;
    for path in &files {
        if args.check {
            check_one_checkfile(path, &args, &base_hasher, &mut files_failed)?;
        } else {
            let result = hash_one_input(path, &args, &base_hasher);
            if let Err(e) = result {
                some_file_failed = true;
                eprintln!("{}: {}: {}", cli::NAME, path.to_string_lossy(), e);
            }
        }
    }

    if args.check && files_failed > 0 {
        eprintln!(
            "{}: WARNING: {} computed checksum{} did NOT match",
            cli::NAME,
            files_failed,
            if files_failed == 1 { "" } else { "s" }
        );
    }
    if some_file_failed || files_failed > 0 {
        Ok(1)
    } else {
        Ok(0)
    }
}

