extern "C" {
    fn mmap(addr: *mut u8, len: usize, prot: i32, flags: i32, fd: i32, offset: i64) -> *mut u8;
    fn munmap(addr: *mut u8, len: usize) -> i32;
}

const PROT_READ: i32 = 1;
const MAP_PRIVATE: i32 = 2;

impl Mmap {
    fn new(file: &File, len: usize) -> Option<Mmap> {
        use std::os::unix::io::AsRawFd;
        let ptr = unsafe { mmap(std::ptr::null_mut(), len, PROT_READ, MAP_PRIVATE, file.as_raw_fd(), 0) };
        if ptr as isize == -1 || ptr.is_null() {
            None
        } else {
            Some(Mmap { ptr, len })
        }
    }

    fn as_slice(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr, self.len) }
    }
}

impl Drop for Mmap {
    fn drop(&mut self) {
        unsafe {
            munmap(self.ptr, self.len);
        }
    }
}

unsafe impl Send for Mmap {}
unsafe impl Sync for Mmap {}

/// Try to map a file when that is worthwhile: regular, non-empty, not tiny.
fn maybe_mmap(file: &File) -> io::Result<Option<Mmap>> {
    let metadata = file.metadata()?;
    let size = metadata.len();
    if !metadata.is_file() || size == 0 || size > isize::MAX as u64 || size < 16 * 1024 {
        return Ok(None);
    }
    Ok(Mmap::new(file, size as usize))
}

fn update_from_reader<R: Read>(hasher: &mut Hasher, mut reader: R) -> io::Result<()> {
    let mut buf = vec![0u8; 1 << 20];
    loop {
        let n = reader.read(&mut buf)?;
        if n == 0 {
            return Ok(());
        }
        hasher.update(&buf[..n]);
    }
}

fn is_stdin(path: &OsString) -> bool {
    path == "-"
}

/// Hash the given input path (or stdin for `-`) into the hasher.
fn hash_input(path: &OsString, args: &Args, base: &Hasher) -> io::Result<Hasher> {
    let mut hasher = base.clone();
    if is_stdin(path) {
        if args.keyed {
            return Err(io::Error::new(io::ErrorKind::Other, "Cannot open `-` in keyed mode"));
        }
        let stdin = io::stdin();
        let lock = stdin.lock();
        update_from_reader(&mut hasher, lock)?;
        return Ok(hasher);
    }
    let mut file = File::open(path)?;
    if !args.no_mmap {
        if let Some(map) = maybe_mmap(&file)? {
            hasher.update(map.as_slice());
            return Ok(hasher);
        }
    }
    update_from_reader(&mut hasher, &mut file)?;
    Ok(hasher)
}

// ----- output -----

fn needs_escape(s: &str) -> bool {
    s.contains('\\') || s.contains('\n') || s.contains('\r')
}

fn escape_name(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            c => out.push(c),
        }
    }
    out
}

fn hex_encode(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut s = String::with_capacity(bytes.len() * 2);
    for &b in bytes {
        s.push(DIGITS[(b >> 4) as usize] as char);
        s.push(DIGITS[(b & 0xf) as usize] as char);
    }
    s
}

/// Stream `len` bytes of output (starting at `seek`) as hex to stdout.
fn print_hex_output(hasher: &Hasher, seek: u64, len: u64) {
    let mut reader = hasher.finalize_xof();
    reader.set_position(seek);
    let mut remaining = len;
    let mut block = [0u8; 4096];
    while remaining > 0 {
        let take = std::cmp::min(remaining, block.len() as u64) as usize;
        reader.fill(&mut block[..take]);
        print!("{}", hex_encode(&block[..take]));
        remaining -= take as u64;
    }
}

/// Stream `len` raw output bytes (starting at `seek`) to stdout.
fn write_raw_output(hasher: &Hasher, seek: u64, len: u64) -> io::Result<()> {
    let mut reader = hasher.finalize_xof();
    reader.set_position(seek);
    let stdout = io::stdout();
    let mut lock = stdout.lock();
    let mut remaining = len;
    let mut block = [0u8; 4096];
    while remaining > 0 {
        let take = std::cmp::min(remaining, block.len() as u64) as usize;
        reader.fill(&mut block[..take]);
        lock.write_all(&block[..take])?;
        remaining -= take as u64;
    }
    Ok(())
}

fn hash_one_input(path: &OsString, args: &Args, base: &Hasher) -> io::Result<()> {
    let hasher = hash_input(path, args, base)?;
    if args.raw {
        write_raw_output(&hasher, args.seek, args.length)?;
        return Ok(());
    }
    if args.no_names {
        print_hex_output(&hasher, args.seek, args.length);
        println!();
        return Ok(());
    }
    let name = path.to_string_lossy();
    let escaped = needs_escape(&name);
    let display = if escaped { escape_name(&name) } else { name.into_owned() };
    if escaped {
        print!("\\");
    }
    if args.tag {
        print!("BLAKE3 ({}) = ", display);
        print_hex_output(&hasher, args.seek, args.length);
        println!();
    } else {
        print_hex_output(&hasher, args.seek, args.length);
        println!("  {}", display);
    }
    Ok(())
}

// ----- checking -----

struct CheckLine {
    /// The path exactly as written in the checkfile (still escaped).
    file_string: String,
    is_escaped: bool,
    /// The path to open.
    file_path: OsString,
    expected: [u8; blake3::OUT_LEN],
}

fn hex_val(c: char) -> Option<u8> {
    match c {
        '0'..='9' => Some(c as u8 - b'0'),
        'a'..='f' => Some(c as u8 - b'a' + 10),
        _ => None,
    }
}

fn parse_hash(hex: &str) -> std::result::Result<[u8; blake3::OUT_LEN], String> {
    if hex.len() != 2 * blake3::OUT_LEN {
        return Err("Invalid hash length".to_owned());
    }
    let mut out = [0u8; blake3::OUT_LEN];
    let mut chars = hex.chars();
    for byte in out.iter_mut() {
        let hi = chars.next().unwrap();
        let lo = chars.next().unwrap();
        match (hex_val(hi), hex_val(lo)) {
            (Some(h), Some(l)) => *byte = (h << 4) | l,
            _ => return Err("Invalid hex".to_owned()),
        }
    }
    Ok(out)
}

fn unescape_path(s: &str) -> std::result::Result<String, String> {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('\\') => out.push('\\'),
            Some('n') => out.push('\n'),
            Some('r') => out.push('\r'),
            _ => return Err("Invalid backslash escape".to_owned()),
        }
    }
    Ok(out)
}

fn parse_check_line(line: &str) -> std::result::Result<CheckLine, String> {
    if line.is_empty() {
        return Err("Empty line".to_owned());
    }
    let (is_escaped, rest) = match line.strip_prefix('\\') {
        Some(r) => (true, r),
        None => (false, line),
    };
    let (hash_text, file_string) = if let Some(bsd) = rest.strip_prefix("BLAKE3 (").and_then(|r| r.rsplit_once(") = ")) {
        (bsd.1, bsd.0)
    } else if let Some((hash, name)) = rest.split_once("  ") {
        (hash, name)
    } else {
        return Err("Invalid check line format".to_owned());
    };
    let expected = parse_hash(hash_text)?;
    if file_string.is_empty() {
        return Err("empty file path".to_owned());
    }
    let file_path = if is_escaped { unescape_path(file_string)? } else { file_string.to_owned() };
    Ok(CheckLine { file_string: file_string.to_owned(), is_escaped, file_path: OsString::from(file_path), expected })
}

fn check_one_line(line: &str, args: &Args, base: &Hasher, files_failed: &mut u64) {
    let parsed = match parse_check_line(line) {
        Ok(p) => p,
        Err(msg) => {
            eprintln!("{}: {}", cli::NAME, msg);
            *files_failed += 1;
            return;
        }
    };
    let display = if parsed.is_escaped { format!("\\{}", parsed.file_string) } else { parsed.file_string.clone() };
    match hash_input(&parsed.file_path, args, base) {
        Ok(hasher) => {
            let mut found = [0u8; blake3::OUT_LEN];
            let mut reader = hasher.finalize_xof();
            reader.set_position(args.seek);
            reader.fill(&mut found);
            if constant_time_eq(&found, &parsed.expected) {
                if !args.quiet {
                    println!("{}: OK", display);
                }
            } else {
                println!("{}: FAILED", display);
                *files_failed += 1;
            }
        }
        Err(e) => {
            println!("{}: FAILED ({})", display, e);
            *files_failed += 1;
        }
    }
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

fn check_one_checkfile(path: &OsString, args: &Args, base: &Hasher, files_failed: &mut u64) -> Result<()> {
    let reader: Box<dyn io::BufRead> = if is_stdin(path) {
        Box::new(io::BufReader::new(io::stdin()))
    } else {
        Box::new(io::BufReader::new(File::open(path)?))
    };
    for line in reader.lines() {
        let line = line?;
        check_one_line(&line, args, base, files_failed);
    }
    Ok(())
}
