//! Multi-input ("wide") compression: hashing several chunks or parent blocks
//! side by side, one per SIMD lane. The code is written lane-wise over fixed
//! size arrays so the compiler can vectorize it for whatever instruction set
//! the wrapper function enables.

use crate::blake3::{BLOCK_LEN, CHUNK_LEN, CHUNK_END, CHUNK_START, IV, MSG_SCHEDULE, PARENT};

#[inline(always)]
fn add<const N: usize>(a: &[u32; N], b: &[u32; N]) -> [u32; N] {
    let mut r = [0u32; N];
    for i in 0..N {
        r[i] = a[i].wrapping_add(b[i]);
    }
    r
}

#[inline(always)]
fn xor<const N: usize>(a: &[u32; N], b: &[u32; N]) -> [u32; N] {
    let mut r = [0u32; N];
    for i in 0..N {
        r[i] = a[i] ^ b[i];
    }
    r
}

#[inline(always)]
fn rot<const N: usize>(a: &[u32; N], n: u32) -> [u32; N] {
    let mut r = [0u32; N];
    for i in 0..N {
        r[i] = a[i].rotate_right(n);
    }
    r
}

#[inline(always)]
fn splat<const N: usize>(x: u32) -> [u32; N] {
    [x; N]
}

macro_rules! g {
    ($a:ident, $b:ident, $c:ident, $d:ident, $mx:expr, $my:expr) => {
        $a = add(&add(&$a, &$b), &$mx);
        $d = rot(&xor(&$d, &$a), 16);
        $c = add(&$c, &$d);
        $b = rot(&xor(&$b, &$c), 12);
        $a = add(&add(&$a, &$b), &$my);
        $d = rot(&xor(&$d, &$a), 8);
        $c = add(&$c, &$d);
        $b = rot(&xor(&$b, &$c), 7);
    };
}

/// One compression of N independent blocks. `cv` holds 8 state words, each a
/// vector across the N lanes; `m` holds the 16 message words likewise.
#[inline(always)]
fn compress_n<const N: usize>(
    cv: &mut [[u32; N]; 8],
    m: &[[u32; N]; 16],
    counter_lo: &[u32; N],
    counter_hi: &[u32; N],
    block_len: u32,
    flags: u32,
) {
    let mut v0 = cv[0];
    let mut v1 = cv[1];
    let mut v2 = cv[2];
    let mut v3 = cv[3];
    let mut v4 = cv[4];
    let mut v5 = cv[5];
    let mut v6 = cv[6];
    let mut v7 = cv[7];
    let mut v8 = splat::<N>(IV[0]);
    let mut v9 = splat::<N>(IV[1]);
    let mut v10 = splat::<N>(IV[2]);
    let mut v11 = splat::<N>(IV[3]);
    let mut v12 = *counter_lo;
    let mut v13 = *counter_hi;
    let mut v14 = splat::<N>(block_len);
    let mut v15 = splat::<N>(flags);
    for s in MSG_SCHEDULE.iter() {
        g!(v0, v4, v8, v12, m[s[0]], m[s[1]]);
        g!(v1, v5, v9, v13, m[s[2]], m[s[3]]);
        g!(v2, v6, v10, v14, m[s[4]], m[s[5]]);
        g!(v3, v7, v11, v15, m[s[6]], m[s[7]]);
        g!(v0, v5, v10, v15, m[s[8]], m[s[9]]);
        g!(v1, v6, v11, v12, m[s[10]], m[s[11]]);
        g!(v2, v7, v8, v13, m[s[12]], m[s[13]]);
        g!(v3, v4, v9, v14, m[s[14]], m[s[15]]);
    }
    cv[0] = xor(&v0, &v8);
    cv[1] = xor(&v1, &v9);
    cv[2] = xor(&v2, &v10);
    cv[3] = xor(&v3, &v11);
    cv[4] = xor(&v4, &v12);
    cv[5] = xor(&v5, &v13);
    cv[6] = xor(&v6, &v14);
    cv[7] = xor(&v7, &v15);
}

/// Hash N whole chunks (each exactly CHUNK_LEN bytes) to chaining values.
#[inline(always)]
unsafe fn hash_chunks_n<const N: usize>(
    inputs: &[*const u8; N],
    key: &[u32; 8],
    chunk_counter: u64,
    flags: u8,
    out: &mut [[u32; 8]; N],
) {
    let mut cv = [[0u32; N]; 8];
    for w in 0..8 {
        cv[w] = splat::<N>(key[w]);
    }
    let mut counter_lo = [0u32; N];
    let mut counter_hi = [0u32; N];
    for i in 0..N {
        let c = chunk_counter.wrapping_add(i as u64);
        counter_lo[i] = c as u32;
        counter_hi[i] = (c >> 32) as u32;
    }
    let blocks = CHUNK_LEN / BLOCK_LEN;
    for block in 0..blocks {
        let mut m = [[0u32; N]; 16];
        for i in 0..N {
            let base = inputs[i].add(block * BLOCK_LEN);
            for j in 0..16 {
                m[j][i] = u32::from_le_bytes(*(base.add(4 * j) as *const [u8; 4]));
            }
        }
