        cv[w] = splat::<N>(key[w]);
    }
    let mut m = [[0u32; N]; 16];
    for i in 0..N {
        for j in 0..16 {
            m[j][i] = blocks[i][j];
        }
    }
    let zero = splat::<N>(0);
    compress_n(&mut cv, &m, &zero, &zero, BLOCK_LEN as u32, (flags | PARENT) as u32);
    for i in 0..N {
        for w in 0..8 {
            out[i][w] = cv[w][i];
        }
    }
}

