/// Combine adjacent pairs of chaining values into parent chaining values,
/// carrying an odd final value through unchanged. Returns the new count.
fn compress_parents_parallel(
    platform: Platform,
    cvs: &[[u32; 8]],
    key: &[u32; 8],
    flags: u8,
    out: &mut [[u32; 8]],
) -> usize {
    let n_pairs = cvs.len() / 2;
    let degree = platform.degree();
    let mut blocks = [[0u32; 16]; MAX_DEGREE];
    let mut done = 0;
    while done < n_pairs {
        let batch = cmp::min(degree, n_pairs - done);
        for i in 0..batch {
            let (l, r) = (&cvs[2 * (done + i)], &cvs[2 * (done + i) + 1]);
