const PARALLEL_THRESHOLD: usize = 128 * 1024;

/// Hash at most `degree` chunks of input (the last one possibly partial),
/// writing one chaining value per chunk. Returns the number of chunks.
fn compress_chunks_parallel(
    platform: Platform,
    input: &[u8],
    key: &[u32; 8],
    chunk_counter: u64,
    flags: u8,
    out: &mut [[u32; 8]],
) -> usize {
